193	    /// the features this disables.
194	    pub fn new_inaccessible(platform: Rc<dyn Platform>) -> Self {
195	        let this = Self::with_platform(platform);
196	        this.0.borrow_mut().accessibility_force_disabled = true;
197	        this
198	    }
